[CmdletBinding(SupportsShouldProcess = $true, ConfirmImpact = 'High')]
param([string] $ConfigPath, [string] $OutputPath = ".\operatoros-output", [switch] $DryRun, [switch] $EnableTranscript, [string] $ScriptVersion = "1.0.0")
$OperatorOSFrameworkPath = Join-Path -Path $PSScriptRoot -ChildPath "..\..\content\scripts\framework\OperatorOS-ScriptFramework.psm1"; Import-Module $OperatorOSFrameworkPath -Force
function Invoke-OperatorOSRetry { param([scriptblock] $Operation, [int] $Attempts = 3) for ($i = 1; $i -le $Attempts; $i++) { try { return & $Operation } catch { if ($i -eq $Attempts) { throw }; Start-Sleep -Seconds ([Math]::Min(10, $i * 2)) } } }
$Context = New-OperatorOSExecutionContext -ScriptName "Security Remediation Template" -SafetyMode Remediation -ConfigPath $ConfigPath -DryRun:$DryRun -EnableTranscript:$EnableTranscript -OutputPath $OutputPath; Add-OperatorOSEvidence -Context $Context -Name "ScriptVersion" -Value $ScriptVersion
try { Assert-OperatorOSPowerShellVersion -MinimumVersion "5.1"; Assert-OperatorOSPermission -PermissionName "Security remediation authority" -ValidationScript { $true }; Register-OperatorOSRollbackAction -Context $Context -Action { Write-OperatorOSLog -Context $Context -Level Warning -Message "Restore security state from exported evidence and change ticket." }; $Results = Invoke-OperatorOSRetry { Invoke-OperatorOSOperation -Context $Context -Name "Apply security remediation" -Operation { @() } }; Export-OperatorOSReport -Context $Context -Data @($Results) -Format Html,Csv,Json; Complete-OperatorOSExecution -Context $Context -FindingCount @($Results).Count -RequiresAdmin:$true } catch { Add-OperatorOSException -Context $Context -Exception $_.Exception -Operation "Security remediation"; Invoke-OperatorOSRollback -Context $Context; throw }
